<template><q-page padding><h4>Dashboard</h4><div class="row q-col-gutter-md"><div v-for="s in stats" :key="s.key" class="col-12 col-sm-6 col-md-3"><q-card class="q-pa-lg"><div class="text-grey-5">{{s.label}}</div><div class="text-h3 q-mt-md">{{s.count}}</div></q-card></div></div><div class="q-mt-lg">VendorPro VMS · Overview</div></q-page></template><script setup>import {ref,onMounted} from 'vue';import {getAll} from '../api';const stats=ref([{key:'vendors',label:'Vendors',count:0},{key:'rfqs',label:'Active RFQs',count:0},{key:'purchase-orders',label:'Purchase Orders',count:0},{key:'invoices',label:'Invoices',count:0}]);onMounted(async()=>{await Promise.all(stats.value.map(async s=>{try{s.count=(await getAll(s.key)).length}catch(e){console.error(e)}}))})</script>